const id='dp-subsequences';setCode(id,`# A subsequence preserves order while allowing skipped characters.
def is_subsequence(s, t):
    if not s:
        return True
    i = 0
    for j, ch in enumerate(t):
        if s[i] == ch:
            i += 1
            if i == len(s):
                return True
    return False

print(is_subsequence("ace", "abcde"))
print(is_subsequence("aec", "abcde"))`,['Comment: a subsequence preserves the original order.','Define the membership test for two strings.','Check the empty candidate before scanning t.','Every string contains the empty subsequence.','i is the next unmatched index in s.','Visit each character of t with its actual text index j.','Test whether this character matches the next needed s character.','Advance the candidate index after a match.','Test whether the match completed the candidate.','Return immediately once all candidate characters are matched.','The scan ended before all matches: return False.','Blank line.','Print True for ace in abcde.','Print False for aec in abcde.']);const x=item(id),c=x.complexityExplanation;c.time.bound='O(n+1)';c.time.explanation='Each examined t character takes constant work, and no character is revisited. At most n are examined: O(n+1), or O(n) for growing positive lengths. Empty s returns immediately in O(1); a candidate completed early stops the scan.';c.space.explanation='Only candidate index i, text index j, and the current character are retained. enumerate does not copy the text.';c.derivation=[{lines:[3,4,5],description:'Handle empty candidate and initialize i.',cost:'O(1)',dimension:'time'},{lines:[6,7,8,9,10,11],description:'Examine at most n text characters, stopping once all are matched.',cost:'O(n+1)',dimension:'time'},{lines:[5,6],description:'Constant number of scalar positions and current character.',cost:'O(1)',dimension:'space'}];c.counters=[{label:'characters examined',definition:'Entries to the match test, before it executes.',countLines:[7]},{label:'matches advanced',definition:'Entries to the candidate-index increment.',countLines:[8]}];c.tradeoffs='Subsequence membership has a greedy earliest-match proof and needs no table. Optimization/counting variants need their own state and correctness proof; quadratic LIS DP is one option, and faster LIS algorithms also exist.';x.bindings=[{variable:'s',model:'string',overlays:[{role:'pointer',label:'i (next candidate)',source:'i'}]},{variable:'t',model:'string',overlays:[{role:'pointer',label:'j (text index)',source:'j'}]}];x.concepts.edgeCases='Empty s returns True without scanning t. Nonempty s with empty t returns False. Repeated characters need separate ordered matches. Inputs are strings.';x.references.push(problem('is-subsequence','LeetCode: Is Subsequence',['A subsequence permits deletion without changing remaining order; empty strings are permitted.']),ref('mit16','MIT 6.006 lecture 16','LIS and LCS state definitions',['Subsequence optimization differs from checking one prescribed candidate.'],['Membership uses greedy earliest matches; LIS/LCS need separate recurrences.']));
